        // ==========================================================
        // GET Reports
        // ==========================================================

        public async Task<List<ReportOutputDTO>> GetReportsAsync(
            NFD_ReportType? type,
            int? userId
        )
        {
            var reports =
                await _repository.GetReportsAsync(
                    type,
                    userId
                );


            return reports
                .Select(r =>
                    new ReportOutputDTO
                    {
                        ReportId =
                            r.ReportId,

                        Type =
                            r.Type,

                        FiltersJson =
                            r.FiltersJson,

                        GeneratedAt =
                            r.GeneratedAt,

                        FileUrl =
                            r.FileUrl,

                        GeneratedByUserId =
                            r.GeneratedByUserId
                    }
                )
                .ToList();
        }


