                                    .FontColor(
                                        "#94A3B8"
                                    );


                                row.RelativeItem()
                                    .AlignRight()
                                    .Text(
                                        "بوابة نفاذ للتدريب والتطوير"
                                    )
                                    .FontSize(8)
                                    .FontColor(
                                        "#94A3B8"
                                    );
                            });
                    });
                });


            // ======================================================
            // Save PDF
            // ======================================================

            document.GeneratePdf(
                fullPath
            );


            // The Trainer Portal stores the absolute physical path
            // because its dedicated endpoint validates and reads it.
            var fileUrl =
                fullPath;


            // ======================================================
            // Save Report Metadata
            // ======================================================

            var report =
                new NFD_Report
                {
                    Type =
                        dto.Type,

                    FiltersJson =
                        dto.FiltersJson,

                    GeneratedAt =
                        generatedAt,

                    FileUrl =
                        fileUrl,

                    GeneratedByUserId =
                        dto.GeneratedByUserId
                };


            await _repository.AddReportAsync(
                report
            );


            // ======================================================
            // Return
            // ======================================================

            return new ReportOutputDTO
            {
                ReportId =
                    report.ReportId,

                Type =
                    report.Type,

                FiltersJson =
                    report.FiltersJson,

                GeneratedAt =
                    report.GeneratedAt,

                FileUrl =
                    report.FileUrl,

                GeneratedByUserId =
                    report.GeneratedByUserId
            };
        }


        // ==========================================================
        // SHARED PDF REPORT
        //
        // Keep this unchanged.
        // Other portals may depend on this behavior.
        // ==========================================================

        public async Task<ReportOutputDTO>
            GenerateReportAsync(
                ReportInputDTO dto
            )
        {
            // مجلد حفظ التقارير
            var reportsFolder =
                Path.Combine(
                    Directory.GetCurrentDirectory(),
                    "wwwroot",
                    "reports"
                );


            // إنشاء المجلد إذا لم يكن موجوداً
            Directory.CreateDirectory(
                reportsFolder
            );


            var generatedAt =
                DateTime.Now;


            // اسم فريد للملف
            var fileName =
                $"trainer-report-{dto.TrainerId ?? 0}-{generatedAt:yyyyMMddHHmmssfff}.pdf";


            var fullPath =
                Path.Combine(
                    reportsFolder,
                    fileName
                );


            // ======================================================
            // جلب مؤشرات المدرب
            // ======================================================

            TrainerKpisDTO? kpis =
                null;


            if (dto.TrainerId.HasValue)
            {
                kpis =
                    await _repository.GetTrainerKpisAsync(
                        dto.TrainerId.Value
                    );
            }


            // ======================================================
            // إنشاء ملف PDF
            // ======================================================

            var document =
                Document.Create(container =>
                {
                    container.Page(page =>
                    {
                        page.Size(
                            PageSizes.A4
                        );


                        page.Margin(
                            30
                        );


                        page.DefaultTextStyle(
                            style =>
                                style.FontSize(12)
                        );


                        // ---------------- Header ----------------

                        page.Header()
                            .AlignCenter()
                            .Text(
                                "تقرير المدرب"
                            )
                            .FontSize(22)
                            .Bold();


                        // ---------------- Content ----------------

                        page.Content()
                            .PaddingVertical(20)
                            .Column(column =>
                            {
                                column.Spacing(
                                    12
                                );


                                column.Item()
                                    .AlignRight()
                                    .Text(
                                        $"نوع التقرير: {dto.Type}"
                                    );


                                if (
                                    dto.TrainerId.HasValue
                                )
                                {
                                    column.Item()
                                        .AlignRight()
                                        .Text(
                                            $"رقم المدرب: {dto.TrainerId.Value}"
                                        );
                                }


                                column.Item()
                                    .AlignRight()
                                    .Text(
                                        $"تاريخ الإنشاء: {generatedAt:yyyy-MM-dd HH:mm}"
                                    );


                                // ----------------------------------
                                // KPIs
                                // ----------------------------------

                                if (kpis != null)
                                {
                                    column.Item()
                                        .PaddingTop(15)
                                        .AlignRight()
                                        .Text(
                                            "مؤشرات الأداء"
                                        )
                                        .FontSize(17)
                                        .Bold();


                                    column.Item()
                                        .AlignRight()
                                        .Text(
                                            $"نسبة الحضور العامة: {kpis.AttendanceRate}%"
                                        );


                                    column.Item()
                                        .AlignRight()
                                        .Text(
                                            $"معدل إنجاز المهام: {kpis.TaskCompletionRate}%"
                                        );


                                    column.Item()
                                        .AlignRight()
                                        .Text(
                                            $"متوسط الدرجات الفنية: {kpis.AvgTechnicalGrade} / 100"
                                        );
                                }


                                // ----------------------------------
                                // Filters
                                // ----------------------------------

                                if (
                                    !string.IsNullOrWhiteSpace(
                                        dto.FiltersJson
                                    )
                                )
                                {
                                    column.Item()
                                        .PaddingTop(15)
                                        .AlignRight()
                                        .Text(
                                            "بيانات التقرير"
                                        )
                                        .FontSize(15)
                                        .Bold();


                                    column.Item()
                                        .AlignRight()
                                        .Text(
                                            dto.FiltersJson
                                        );
                                }
                            });


                        // ---------------- Footer ----------------

                        page.Footer()
                            .AlignCenter()
                            .Text(text =>
                            {
                                text.Span(
                                    "بوابة نفاذ - "
                                );

                                text.Span(
                                    "تقرير المدرب"
                                );
                            });
                    });
                });


            // حفظ PDF داخل wwwroot/reports
            document.GeneratePdf(
                fullPath
            );


            // نخزن المسار النسبي فقط في قاعدة البيانات
            var fileUrl =
                $"reports/{fileName}";


            // ======================================================
            // حفظ سجل التقرير في قاعدة البيانات
            // ======================================================

            var report =
                new NFD_Report
                {
                    Type =
                        dto.Type,

                    FiltersJson =
                        dto.FiltersJson,

                    GeneratedAt =
                        generatedAt,

                    FileUrl =
                        fileUrl,

                    GeneratedByUserId =
                        dto.GeneratedByUserId
                };


            await _repository.AddReportAsync(
                report
            );


            // ======================================================
            // Return
            // ======================================================

            return new ReportOutputDTO
            {
                ReportId =
                    report.ReportId,

                Type =
                    report.Type,

                FiltersJson =
                    report.FiltersJson,

                GeneratedAt =
                    report.GeneratedAt,

                FileUrl =
                    report.FileUrl,

                GeneratedByUserId =
                    report.GeneratedByUserId
            };
        }


        // ==========================================================
        // Generate Trainer Trainees PDF Report
        //
        // Existing report used by another Trainer feature.
        // Kept separate from Trainer Portal report generation.
        // ==========================================================

        public async Task<ReportOutputDTO>
            GenerateTrainerTraineesReportAsync(
                TrainerTraineesReportInputDto dto
            )
        {
            // ======================================================
            // Get Trainee Rows
            // ======================================================

            var rows =
                await _repository
                    .GetTrainerTraineesReportRowsAsync(
                        dto.TrainerId,
                        dto.BatchId
                    );


            // ======================================================
            // Reports Folder
            // ======================================================

            var reportsFolder =
                Path.Combine(
                    @"C:\NafadhStorage",
                    "Reports"
                );


            Directory.CreateDirectory(
                reportsFolder
            );


            var generatedAt =
                DateTime.Now;


            var fileName =
                $"trainer-trainees-{dto.TrainerId}-{generatedAt:yyyyMMddHHmmssfff}.pdf";


            var fullPath =
                Path.Combine(
                    reportsFolder,
                    fileName
                );


            // ======================================================
            // Generate PDF
            // ======================================================

            var document =
                Document.Create(container =>
                {
                    container.Page(page =>
                    {
                        page.Size(
                            PageSizes.A4.Landscape()
                        );


                        page.Margin(
                            30
                        );


                        page.DefaultTextStyle(
                            style =>
                                style.FontSize(10)
                        );


                        // ------------------------------------------
                        // Header
                        // ------------------------------------------

                        page.Header()
                            .Column(header =>
                            {
                                header.Item()
                                    .AlignCenter()
                                    .Text(
                                        "كشف تقييم ومتابعة المتدربين"
                                    )
                                    .FontSize(20)
                                    .Bold();


                                header.Item()
                                    .PaddingTop(6)
                                    .AlignCenter()
                                    .Text(
                                        $"رقم المدرب: {dto.TrainerId}"
                                    )
                                    .FontSize(10);


                                if (
                                    dto.BatchId.HasValue
                                )
                                {
                                    header.Item()
                                        .PaddingTop(3)
                                        .AlignCenter()
                                        .Text(
                                            $"رقم الدفعة: {dto.BatchId.Value}"
                                        )
                                        .FontSize(10);
                                }


                                header.Item()
                                    .PaddingTop(3)
                                    .AlignCenter()
                                    .Text(
                                        $"تاريخ التصدير: {generatedAt:yyyy-MM-dd HH:mm}"
                                    )
                                    .FontSize(10);
                            });


                        // ------------------------------------------
                        // Content
                        // ------------------------------------------

                        page.Content()
                            .PaddingVertical(20)
                            .Column(column =>
                            {
                                column.Spacing(
                                    10
                                );


                                if (
                                    rows.Count == 0
                                )
                                {
                                    column.Item()
                                        .AlignCenter()
                                        .PaddingTop(40)
                                        .Text(
                                            "لا يوجد متدربون متاحون لهذا الكشف."
                                        )
                                        .FontSize(14);


                                    return;
                                }


                                column.Item()
                                    .Table(table =>
                                    {
                                        // --------------------------
                                        // Columns
                                        // --------------------------

                                        table.ColumnsDefinition(
                                            columns =>
                                            {
                                                columns.ConstantColumn(
                                                    70
                                                );

                                                columns.RelativeColumn(
                                                    2
                                                );

                                                columns.RelativeColumn(
                                                    2
                                                );

                                                columns.RelativeColumn(
                                                    1.3f
                                                );

                                                columns.RelativeColumn(
                                                    1.3f
                                                );

                                                columns.RelativeColumn(
                                                    1.3f
                                                );
                                            }
                                        );


                                        // --------------------------
                                        // Table Header
                                        // --------------------------

                                        table.Header(header =>
                                        {
                                            header.Cell()
                                                .Border(1)
                                                .Padding(7)
                                                .AlignCenter()
                                                .Text(
                                                    "رقم التسجيل"
                                                )
                                                .Bold();


                                            header.Cell()
                                                .Border(1)
                                                .Padding(7)
                                                .AlignCenter()
                                                .Text(
                                                    "المتدرب"
                                                )
                                                .Bold();


                                            header.Cell()
                                                .Border(1)
                                                .Padding(7)
                                                .AlignCenter()
                                                .Text(
                                                    "الدفعة"
                                                )
                                                .Bold();


                                            header.Cell()
                                                .Border(1)
                                                .Padding(7)
                                                .AlignCenter()
                                                .Text(
                                                    "المستوى التقني"
                                                )
                                                .Bold();


                                            header.Cell()
                                                .Border(1)
                                                .Padding(7)
                                                .AlignCenter()
                                                .Text(
                                                    "نسبة الحضور"
                                                )
                                                .Bold();


                                            header.Cell()
                                                .Border(1)
                                                .Padding(7)
                                                .AlignCenter()
                                                .Text(
                                                    "متوسط التقييم"
                                                )
                                                .Bold();
                                        });


                                        // --------------------------
                                        // Table Rows
                                        // --------------------------

                                        foreach (
                                            var row
                                            in rows
                                        )
                                        {
                                            table.Cell()
                                                .Border(1)
                                                .Padding(6)
                                                .AlignCenter()
                                                .Text(
                                                    row.EnrollmentId
                                                        .ToString()
                                                );


                                            table.Cell()
                                                .Border(1)
                                                .Padding(6)
                                                .AlignRight()
                                                .Text(
                                                    row.TraineeName
                                                    ?? "—"
                                                );


                                            table.Cell()
                                                .Border(1)
                                                .Padding(6)
                                                .AlignRight()
                                                .Text(
                                                    row.BatchName
                                                    ?? "—"
                                                );


                                            table.Cell()
                                                .Border(1)
                                                .Padding(6)
                                                .AlignCenter()
                                                .Text(
                                                    row.TechnicalLevel
                                                );


                                            table.Cell()
                                                .Border(1)
                                                .Padding(6)
                                                .AlignCenter()
                                                .Text(
                                                    $"{row.AttendancePercentage:0.#}%"
                                                );


                                            table.Cell()
                                                .Border(1)
                                                .Padding(6)
                                                .AlignCenter()
                                                .Text(
                                                    $"{row.AverageScore:0.#}%"
                                                );
                                        }
                                    });
                            });


                        // ------------------------------------------
                        // Footer
                        // ------------------------------------------

                        page.Footer()
                            .AlignCenter()
                            .Text(text =>
                            {
                                text.Span(
                                    "بوابة نفاذ - كشف المتدربين"
                                );
                            });
                    });
                });


            // ======================================================
            // Save PDF
            // ======================================================

            document.GeneratePdf(
                fullPath
            );


            var fileUrl =
                fullPath;


            // ======================================================
            // Save Report Record
            // ======================================================

            var report =
                new NFD_Report
                {
                    Type =
                        NFD_ReportType.Performance,

                    FiltersJson =
                        dto.BatchId.HasValue
                            ? $"BatchId: {dto.BatchId.Value}"
                            : null,

                    GeneratedAt =
                        generatedAt,

                    FileUrl =
                        fileUrl,

                    GeneratedByUserId =
                        dto.GeneratedByUserId
                };


            await _repository.AddReportAsync(
                report
            );


            // ======================================================
            // Return
            // ======================================================

            return new ReportOutputDTO
            {
                ReportId =
                    report.ReportId,

                Type =
                    report.Type,

                FiltersJson =
                    report.FiltersJson,

                GeneratedAt =
                    report.GeneratedAt,

                FileUrl =
                    report.FileUrl,

                GeneratedByUserId =
                    report.GeneratedByUserId
            };
        }


