        // ==========================================================
        // Trainer Portal Report File
        // ==========================================================

        // Resolves Trainer Portal reports only from the configured
        // external folder without affecting shared report downloads.
        public async Task<string?>
            GetTrainerPortalReportFilePathAsync(
                int reportId
            )
        {
            var report =
                await GetReportByIdAsync(
                    reportId
                );


            if (
                report == null ||
                string.IsNullOrWhiteSpace(
                    report.FileUrl
                )
            )
            {
                return null;
            }


            var reportsFolder =
                _configuration[
                    "Storage:TrainerReportsPath"
                ];


            if (
                string.IsNullOrWhiteSpace(
                    reportsFolder
                )
            )
            {
                return null;
            }


            var reportsRoot =
                Path.GetFullPath(
                    reportsFolder
                );


            var filePath =
                Path.GetFullPath(
                    report.FileUrl
                );


            var rootWithSeparator =
                reportsRoot.TrimEnd(
                    Path.DirectorySeparatorChar,
                    Path.AltDirectorySeparatorChar
                )
                + Path.DirectorySeparatorChar;


            // Prevent the Trainer Portal endpoint from
            // reading files outside its configured folder.
            if (
                !filePath.StartsWith(
                    rootWithSeparator,
                    StringComparison.OrdinalIgnoreCase
                )
            )
            {
                return null;
            }


            var fileName =
                Path.GetFileName(
                    filePath
                );


            // Only PDFs generated by the dedicated
            // Trainer Portal generator are accepted.
            if (
                !fileName.StartsWith(
                    "trainer-portal-report-",
                    StringComparison.OrdinalIgnoreCase
                )
            )
            {
                return null;
            }


            if (
                !string.Equals(
                    Path.GetExtension(fileName),
                    ".pdf",
                    StringComparison.OrdinalIgnoreCase
                )
            )
            {
                return null;
            }


            if (
                !File.Exists(
                    filePath
                )
            )
            {
                return null;
            }


            return filePath;
        }


